import {GymRepository,GYM_KEY,gymDate,moveGymEntry,migrateGym,gymPreferences,safeURL} from './gym.js';
import {descriptionLinks,descriptionURLs,videoInfo,createGymMedia} from './gym-media.js';
import {uid,PALETTE} from './domain.js';
import {checkForm,submitOnce} from './forms.js';

export function createGymUI({storage,esc,icon,openModal,closeModal,toast,render,download,target=window,now=()=>new Date()}){
  const repo=new GymRepository(storage,target),media=createGymMedia({fetcher:(...args)=>target.fetch(...args)});
  let selected='',error='',orderMode=false,renderedDate='',preferences=gymPreferences();
  const date=()=>gymDate(now());
  function load(){try{const s=repo.load();error='';return s}catch(e){error=e.message;return null}}
  const current=s=>s.workouts.find(w=>w.id===selected)||s.workouts[0];
  const expected=w=>({id:w.id,value:JSON.stringify(w)});
  function workout(s,id){const w=s.workouts.find(w=>w.id===id);if(!w)throw Error('Este treino não está mais disponível.');return w}
  async function save(operation,message,{scope=null,refresh=()=>render(),...options}={}){try{const saved=await repo.commit(operation,options);refresh(saved);toast(message);return true}catch(e){const el=scope?.isConnected?scope.querySelector('.formerror'):null;if(el)el.textContent=e.message;else toast(e.message);return false}}
  function links(text){
    let result='',offset=0;
    for(const link of descriptionURLs(text)){result+=esc(text.slice(offset,link.start));result+=`<a href="${esc(link.url)}" target="_blank" rel="noopener noreferrer">${esc(link.label)}</a>`;offset=link.end}
    return result+esc(text.slice(offset));
  }
  function thumbnails(e,p=preferences){
    const videos=descriptionLinks(e.description).map(videoInfo).filter(Boolean).slice(0,10),custom=safeURL(e.thumbnail);
    if(!videos.length&&!custom)return '';
    if(p.thumbnails==='hidden')return videos.length?`<div class="gym-video-links">${videos.map(v=>`<a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">${icon('play')} Ver vídeo · ${v.provider}</a>`).join('')}</div>`:'';
    return `<div class="gym-videos">${videos.length?videos.map((v,i)=>`<a class="gym-video" href="${esc(v.url)}" target="_blank" rel="noopener noreferrer" aria-label="Abrir demonstração de ${esc(e.name)} no ${v.provider}" ${!custom||i>0?`data-gym-video="${esc(v.url)}"`:''}>${custom&&i===0?`<img data-gym-thumbnail src="${esc(custom)}" loading="lazy" referrerpolicy="no-referrer" alt="Miniatura de ${esc(e.name)}">`:''}<span class="gym-video-placeholder">${icon('play')}</span><span class="gym-video-label">${icon('play')} ${v.provider} · Ver vídeo</span></a>`).join(''):`<div class="gym-video gym-image"><img data-gym-thumbnail src="${esc(custom)}" loading="lazy" referrerpolicy="no-referrer" alt="${esc(e.name)}"></div>`}</div>`;
  }
  const colorStyle=color=>color?`style="--gym-color:${color};--accent:color-mix(in srgb,${color} 68%,#132c37);--accent-end:color-mix(in srgb,${color} 78%,#253347);--soft:color-mix(in srgb,${color} 14%,transparent)"`:'';
  function card(w,e,index,s,date){
    const p=s.preferences,done=s.sessions[date]?.[e.id]===true,color=p.exerciseColors[e.id]||p.workoutColors[w.id]||p.accent;
    return `<article class="gym-exercise ${done?'gym-done':''} ${color?'gym-colored':''}" ${colorStyle(color)} data-gym-exercise="${esc(e.id)}"><div class="gym-exercise-main"><div class="gym-exercise-head"><label class="gym-check"><input type="checkbox" id="gym-check-${esc(e.id)}" data-gym-date="${date}" data-gym-check="${esc(e.id)}" data-workout="${esc(w.id)}" ${done?'checked':''}><span class="sr-only">Marcar ${esc(e.name)} como feito hoje</span></label><div class="gym-exercise-title"><h3>${esc(e.name)}</h3><div class="gym-prescription">${[[e.sets,'séries'],[e.reps,'repetições'],[e.rest,'descanso'],[e.load,'carga']].filter(([v])=>v).map(([v,label])=>`<span><b>${esc(v)}</b> ${label}</span>`).join('')}</div></div><button class="iconbtn" data-action="gym-edit-exercise" data-workout="${esc(w.id)}" data-id="${esc(e.id)}" aria-label="Editar ${esc(e.name)}">${icon('edit')}</button></div>${thumbnails(e,p)}${e.description&&p.descriptions!=='hidden'?`<details class="gym-description" ${p.descriptions==='open'?'open':''}><summary>Execução e descrição</summary><p>${links(e.description)}</p></details>`:''}</div>${orderMode?`<div class="gym-order"><span>Posição ${index+1} de ${w.exercises.length}</span><div><button class="iconbtn" data-action="gym-move-exercise" data-workout="${esc(w.id)}" data-id="${esc(e.id)}" data-delta="-1" aria-label="Subir ${esc(e.name)}" ${index===0?'disabled':''}>${icon('up')}</button><button class="iconbtn" data-action="gym-move-exercise" data-workout="${esc(w.id)}" data-id="${esc(e.id)}" data-delta="1" aria-label="Descer ${esc(e.name)}" ${index===w.exercises.length-1?'disabled':''}>${icon('down')}</button></div></div>`:''}</article>`;
  }
  function page(){
    const s=load(),heading='<div class="page-heading"><h1>Academia</h1><p>Seu roteiro de treinos, um exercício por vez.</p></div>';
    if(!s)return `${heading}<div class="errorbanner" role="alert">${esc(error)}</div>${backup()}`;
    const p=s.preferences,w=current(s),day=date();preferences=p;renderedDate=day;if(w)selected=w.id;
    const done=w?w.exercises.filter(e=>s.sessions[day]?.[e.id]).length:0;
    const exercises=w?w.exercises.filter(e=>p.showCompleted||!s.sessions[day]?.[e.id]||orderMode):[];
    return `<div class="gym-page gym-layout-${p.layout} gym-thumbnails-${p.thumbnails}" data-gym-workout="${esc(w?.id||'')}" ${colorStyle(p.accent)}>${heading}<div class="gym-top-actions"><span class="gym-caption">${s.workouts.length} treinos · ${p.layout==='list'?'Lista':'Cartões'}</span><div class="gym-section-actions"><button class="btn secondary" data-action="gym-personalize">${icon('appearance')} Personalizar</button><button class="btn secondary" data-action="gym-new-workout">${icon('plus')} Novo treino</button></div></div><nav class="gym-tabs" data-swipe-scope="workouts" aria-label="Escolher treino">${s.workouts.map(x=>`<button data-action="gym-select" data-id="${esc(x.id)}" class="gym-tab ${w?.id===x.id?'active':''}" ${colorStyle(p.workoutColors[x.id]||'')} aria-pressed="${w?.id===x.id}"><strong>${esc(x.name)}</strong><span>${esc(x.day||x.focus||'Sem dia fixo')}</span></button>`).join('')}</nav>${w?`<div class="gym-workout-content" data-swipe-scope="workouts"><section class="gym-overview" ${colorStyle(p.workoutColors[w.id]||p.accent)}><div class="gym-workout-heading"><div><span class="gym-caption">${esc(w.focus)}</span><h2>${esc(w.name)}</h2></div><button class="btn secondary" data-action="gym-edit-workout" data-id="${esc(w.id)}">${icon('edit')} Editar treino</button></div>${w.description?`<p class="gym-intro">${esc(w.description)}</p>`:''}<div class="gym-stages">${w.warmup?`<div>${icon('resume')}<span>Aquecimento<strong>${esc(w.warmup)}</strong></span></div>`:''}<div>${icon('gym')}<span>Exercícios<strong>${w.exercises.length} no roteiro</strong></span></div>${p.showCardio&&w.cardio?`<div>${icon('clock')}<span>Caminhada<strong>${esc(w.cardio)}</strong></span></div>`:''}</div>${p.showProgress?`<div class="gym-progress-head"><span>${done} de ${w.exercises.length} feitos hoje</span><time datetime="${day}">${new Date(day+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</time></div><progress class="gym-progress" max="${Math.max(1,w.exercises.length)}" value="${done}" aria-label="Exercícios feitos hoje"></progress>`:''}</section><div class="gym-section-heading"><div><h2>Exercícios</h2>${p.swipe&&s.workouts.length>1?'<p class="gym-gesture-hint">Deslize para os lados para trocar de treino.</p>':''}</div><div class="gym-section-actions"><button class="btn secondary" data-action="gym-order" aria-pressed="${orderMode}">${icon('sort')} ${orderMode?'Concluir ordem':'Organizar'}</button><button class="btn primary" data-action="gym-new-exercise" data-workout="${esc(w.id)}">${icon('plus')} Exercício</button></div></div>${orderMode?'<p class="gym-order-help">Use os botões para subir ou descer cada exercício. A ordem é salva automaticamente.</p>':''}<div class="gym-exercises">${exercises.map(e=>card(w,e,w.exercises.indexOf(e),s,day)).join('')||`<p class="gym-empty">${w.exercises.length?'Todos os exercícios deste treino foram feitos hoje.':'Adicione o primeiro exercício deste treino.'}</p>`}</div>${p.showCardio&&(w.cardio||w.cardioNotes)?`<section class="gym-note"><h3>Caminhada ${esc(w.cardio)}</h3><p>${esc(w.cardioNotes)}</p></section>`:''}${p.showGuidance&&w.notice?`<aside class="gym-note gym-guidance"><h3>Orientações do treino</h3><p>${esc(w.notice)}</p></aside>`:''}</div>`:'<p class="gym-empty">Crie um treino para começar seu roteiro.</p>'}${backup()}</div>`;
  }
  function backup(){return `<details class="gym-backup"><summary>Dados e backup da Academia</summary><p>Treinos, personalização e marcações ficam neste navegador. O backup e a sincronização do Planejamento não incluem a Academia. Baixe uma cópia aqui para guardar ou transferir para outro aparelho. As marcações de exercícios são separadas por dia.</p><div class="gym-section-actions"><button class="btn secondary" data-action="gym-export">${icon('download')} Baixar treinos</button><button class="btn secondary" data-action="gym-import">${icon('upload')} Restaurar treinos</button></div><input hidden type="file" id="gym-backup-file" accept="application/json,.json"></details>`}
  const field=(name,label,value,max=200,multiline=false)=>`<div class="field"><label for="gym-${name}">${label}</label><${multiline?'textarea':'input'} id="gym-${name}" name="${name}" maxlength="${max}" ${name==='name'?'required':''} ${multiline?'rows="4"':`value="${esc(value)}"`}>${multiline?esc(value)+'</textarea>':''}</div>`;
  function colorControls(scope,color,fallback='#067f79',inheritLabel='Usar a cor da guia'){
    return `<fieldset class="gym-color-picker"><legend>Cor</legend><label class="gym-option"><input type="checkbox" id="gym-${scope}-inherit" name="inheritColor" ${color?'':'checked'}><span>${inheritLabel}</span></label><div class="gym-palette" role="group" aria-label="Cores disponíveis">${PALETTE.map(([value,label])=>`<button type="button" data-gym-color="${value}" aria-label="Cor ${esc(label)}" aria-pressed="${value===color}" style="--choice-color:${value}"><span></span></button>`).join('')}</div><div class="field"><label for="gym-${scope}-color">Cor personalizada</label><input type="color" id="gym-${scope}-color" name="color" value="${color||fallback}" ${color?'':'disabled'}></div></fieldset>`;
  }
  function bindColor(root,scope){
    const inherit=root.querySelector(`#gym-${scope}-inherit`),color=root.querySelector(`#gym-${scope}-color`);
    const refresh=()=>{color.disabled=inherit.checked;root.querySelectorAll('[data-gym-color]').forEach(button=>button.setAttribute('aria-pressed',String(!inherit.checked&&button.dataset.gymColor===color.value)))};
    inherit.addEventListener('change',refresh);color.addEventListener('input',refresh);
    root.querySelectorAll('[data-gym-color]').forEach(button=>{button.onclick=()=>{inherit.checked=false;color.value=button.dataset.gymColor;refresh();color.dispatchEvent(new target.Event('change',{bubbles:true}))}});refresh();return refresh;
  }
  function takeColor(values){const value=values.inheritColor?'':values.color||'';delete values.inheritColor;delete values.color;return value}
  function setColor(s,kind,id,value,previous){const map=s.preferences[kind];if((map[id]||'')!==previous)throw Error('A cor mudou em outra janela. Reabra o formulário para conferir.');if(value)map[id]=value;else delete map[id]}
  function personalize(){
    const s=load();if(!s){toast(error);return}const p=s.preferences,snapshot=JSON.stringify(p);let colors={workoutColors:structuredClone(p.workoutColors),exerciseColors:structuredClone(p.exerciseColors)};
    const select=(key,label,options)=>`<div class="field"><label for="gym-pref-${key}">${label}</label><select id="gym-pref-${key}" name="${key}">${options.map(([value,text])=>`<option value="${value}" ${p[key]===value?'selected':''}>${text}</option>`).join('')}</select></div>`;
    const check=(key,label)=>`<label class="gym-option"><input type="checkbox" name="${key}" ${p[key]?'checked':''}><span>${label}</span></label>`;
    const root=openModal('Personalizar Academia',`<form id="gym-personalize-form">${colorControls('guide',p.accent,'#067f79','Seguir a cor do Retomar')}<fieldset class="gym-preference-group"><legend>Visualização</legend>${select('layout','Organização dos exercícios',[['cards','Cartões'],['list','Lista']])}${select('thumbnails','Miniaturas de vídeo',[['large','Grandes'],['compact','Compactas'],['hidden','Somente links']])}${select('descriptions','Descrições dos exercícios',[['collapsed','Recolhidas'],['open','Abertas'],['hidden','Ocultas']])}</fieldset><fieldset class="gym-preference-group"><legend>Durante o treino</legend>${check('showProgress','Mostrar progresso do dia')}${check('showCardio','Mostrar caminhada')}${check('showGuidance','Mostrar orientações do treino')}${check('showCompleted','Mostrar exercícios feitos')}${check('swipe','Deslizar para trocar de treino')}</fieldset><p class="field-help">As escolhas são salvas com os treinos neste aparelho e entram no backup da Academia. As cores de cada treino e exercício podem ser alteradas nos respectivos editores.</p><button class="textbtn" type="button" id="gym-pref-reset">Restaurar aparência padrão</button>${formActions()}</form>`);
    const form=root.querySelector('form'),refreshColor=bindColor(root,'guide');root.querySelector('#gym-cancel').onclick=()=>closeModal();
    root.querySelector('#gym-pref-reset').onclick=()=>{const defaults=gymPreferences();colors={workoutColors:{},exerciseColors:{}};for(const [key,value] of Object.entries(defaults)){const input=form.elements.namedItem(key);if(input){if(input.type==='checkbox')input.checked=value;else input.value=value}}form.elements.inheritColor.checked=true;form.elements.color.value='#067f79';refreshColor();form.dispatchEvent(new target.Event('change',{bubbles:true}))};
    form.onsubmit=submitOnce(async()=>{if(!checkForm(form))return;const values=Object.fromEntries(new FormData(form)),next={...gymPreferences(),...colors};next.accent=takeColor(values);for(const key of ['layout','thumbnails','descriptions'])next[key]=values[key];for(const key of ['showProgress','showCardio','showGuidance','showCompleted','swipe'])next[key]=form.elements[key].checked;const button=form.querySelector('[type=submit]');button.disabled=true;const ok=await save(state=>{state.preferences=next},'Personalização da Academia salva.',{scope:form,expectedPreferences:snapshot});if(form.isConnected){if(ok)closeModal(true);else button.disabled=false}});
  }
  function formActions(remove=false){return `<div class="formerror" role="alert"></div><div class="dialogactions">${remove?'<button type="button" class="btn danger" id="gym-delete">Excluir</button>':''}<button type="button" class="btn secondary" id="gym-cancel">Cancelar</button><button type="submit" class="btn primary">Salvar</button></div>`}
  function bindForm(root,operation,{remove,options}={}){
    const form=root.querySelector('form');
    root.querySelector('#gym-cancel').onclick=()=>closeModal();
    form.onsubmit=submitOnce(async e=>{e.preventDefault();if(!checkForm(form))return;const values=Object.fromEntries(new FormData(form));if(!values.name.trim()){form.querySelector('.formerror').textContent='Informe um nome para continuar.';return}const btn=form.querySelector('[type=submit]');btn.disabled=true;const ok=await save(s=>operation(s,values),'Academia salva neste aparelho.',{...options,scope:form});if(form.isConnected){if(ok)closeModal(true);else btn.disabled=false}});
    const del=root.querySelector('#gym-delete');if(del)del.onclick=submitOnce(async()=>{if(!target.confirm('Excluir este '+(remove.kind==='workout'?'treino e todos os seus exercícios':'exercício')+'?'))return;del.disabled=true;const ok=await save(remove.run,'Exclusão salva.',{...options,scope:form});if(form.isConnected){if(ok)closeModal(true);else del.disabled=false}});
  }
  function editWorkout(id){
    const s=load();if(!s){toast(error);return}const w=id?workout(s,id):{id:uid(),name:'',focus:'',day:'',description:'',warmup:'',cardio:'',cardioNotes:'',notice:'',exercises:[]},options=id?{expected:expected(w)}:{},previousColor=s.preferences.workoutColors[w.id]||'';
    const root=openModal(id?'Editar treino':'Novo treino',`<form id="gym-workout-form">${field('name','Nome do treino',w.name,100)}${colorControls('workout',previousColor,s.preferences.accent||'#067f79')}${field('focus','Foco',w.focus)}${field('day','Dia ou frequência',w.day)}${field('description','Descrição do treino',w.description,5000,true)}${field('warmup','Aquecimento',w.warmup)}${field('cardio','Duração da caminhada',w.cardio)}${field('cardioNotes','Orientações da caminhada',w.cardioNotes,5000,true)}${field('notice','Orientações do treino',w.notice,5000,true)}${id?`<div class="field"><label for="gym-position">Posição entre os treinos</label><select id="gym-position" name="position">${s.workouts.map((x,i)=>`<option value="${i}" ${x.id===w.id?'selected':''}>${i+1}</option>`).join('')}</select></div>`:''}${formActions(!!id)}</form>`);
    bindColor(root,'workout');
    bindForm(root,(next,values)=>{const color=takeColor(values);setColor(next,'workoutColors',w.id,color,previousColor);const position=values.position;delete values.position;const updated={...w,...values,name:values.name.trim()};if(id){const index=next.workouts.findIndex(x=>x.id===id);next.workouts.splice(index,1);next.workouts.splice(Number(position),0,updated)}else next.workouts.push(updated);selected=w.id;},{options,remove:id?{kind:'workout',run:next=>{const removed=workout(next,id);next.workouts=next.workouts.filter(x=>x.id!==id);delete next.preferences.workoutColors[id];for(const e of removed.exercises)delete next.preferences.exerciseColors[e.id];for(const entries of Object.values(next.sessions))for(const e of removed.exercises)delete entries[e.id]}}:undefined});
  }
  function editExercise(workoutId,id){
    const s=load();if(!s){toast(error);return}const w=workout(s,workoutId),e=id?w.exercises.find(x=>x.id===id):{id:uid(),name:'',sets:'',reps:'',rest:'',load:'',description:'',thumbnail:''};if(!e){toast('Este exercício não está mais disponível.');return}const previousColor=s.preferences.exerciseColors[e.id]||'';
    const root=openModal(id?'Editar exercício':'Novo exercício',`<form id="gym-exercise-form">${field('name','Nome do exercício',e.name,200)}${colorControls('exercise',previousColor,s.preferences.workoutColors[w.id]||s.preferences.accent||'#067f79','Usar a cor do treino')}<div class="gym-form-grid">${field('sets','Séries',e.sets,100)}${field('reps','Repetições',e.reps,100)}${field('rest','Descanso',e.rest,100)}${field('load','Carga / referência',e.load,100)}</div>${field('description','Descrição e links dos vídeos',e.description,10000,true)}<p class="field-help">Cole os links de YouTube ou Vimeo no texto acima. As miniaturas aparecem automaticamente. Você pode incluir mais de um vídeo.</p><div id="gym-media-preview" class="gym-media-preview" aria-live="polite"></div>${field('thumbnail','Imagem da miniatura (opcional, link https://)',e.thumbnail,2000)}<p class="field-help">Use uma imagem própria se o vídeo não fornecer miniatura. Deixe vazio para usar a imagem automática.</p>${formActions(!!id)}</form>`);
    bindColor(root,'exercise');
    const form=root.querySelector('#gym-exercise-form');let previewTimer;const preview=()=>{clearTimeout(previewTimer);previewTimer=setTimeout(()=>{if(!form.isConnected)return;const out=form.querySelector('#gym-media-preview');out.innerHTML=thumbnails({...e,description:form.querySelector('#gym-description').value,thumbnail:form.querySelector('#gym-thumbnail').value});media.hydrate(out);},250)};
    root.querySelector('#gym-description').addEventListener('input',preview);root.querySelector('#gym-thumbnail').addEventListener('input',preview);preview();
    bindForm(root,(next,values)=>{const color=takeColor(values);setColor(next,'exerciseColors',e.id,color,previousColor);if(values.thumbnail&&!safeURL(values.thumbnail))throw Error('Use um link https:// válido para a miniatura.');const list=workout(next,workoutId).exercises,updated={...e,...values,name:values.name.trim()};if(id)list.splice(list.findIndex(x=>x.id===id),1,updated);else list.push(updated);},{options:{expected:expected(w)},remove:id?{kind:'exercise',run:next=>{const current=workout(next,workoutId);current.exercises=current.exercises.filter(x=>x.id!==id);delete next.preferences.exerciseColors[id];for(const entries of Object.values(next.sessions))delete entries[id]}}:undefined});
  }
  async function importFile(event){
    const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>5*1024*1024){toast('O arquivo excede o limite de 5 MB.');return}let candidate;try{candidate=migrateGym(JSON.parse(await file.text()))}catch(e){toast('Treinos não restaurados. '+e.message);return}
    if(document.querySelector('dialog[open]')){toast('Feche o formulário aberto antes de restaurar a Academia.');return}
    let base;try{base=storage.getItem(GYM_KEY)}catch{toast('Não foi possível acessar os treinos neste navegador. A restauração foi cancelada.');return}
    const root=openModal('Restaurar Academia',`<p class="confirmtext">Este arquivo contém ${candidate.workouts.length} treinos. A restauração substitui os treinos e as marcações da Academia neste aparelho. Primeiro, baixe uma cópia dos dados atuais.</p><div class="formerror" role="alert"></div><div class="dialogactions"><button class="btn secondary" id="gym-cancel">Cancelar</button><button class="btn secondary" id="gym-copy">Baixar cópia atual</button><button class="btn primary" id="gym-restore" disabled>Restaurar Academia</button></div>`);
    const dialog=root.querySelector('dialog'),copy=dialog.querySelector('#gym-copy'),restore=dialog.querySelector('#gym-restore');root.querySelector('#gym-cancel').onclick=()=>closeModal();copy.onclick=()=>{try{download(base!==null?base:JSON.stringify(repo.load(),null,2),'retomar-academia-antes-da-restauracao-'+Date.now()+'.json');restore.disabled=false;dialog.querySelector('.formerror').textContent=''}catch(e){restore.disabled=true;dialog.querySelector('.formerror').textContent=e.message}};
    restore.onclick=submitOnce(async()=>{restore.disabled=true;const ok=await save(()=>{},'Academia restaurada neste aparelho.',{replace:candidate,expectedRaw:base,scope:dialog});if(ok){selected='';render();if(dialog.isConnected)closeModal(true)}else if(dialog.isConnected)restore.disabled=false;});
  }
  async function action(name,d){
    try{
      if(name==='gym-personalize')personalize();
      else if(name==='gym-select'){selected=d.id;render()}
      else if(name==='gym-order'){orderMode=!orderMode;render()}
      else if(name==='gym-new-workout'||name==='gym-edit-workout')editWorkout(d.id);
      else if(name==='gym-new-exercise'||name==='gym-edit-exercise')editExercise(d.workout,d.id);
      else if(name==='gym-move-exercise'){await save(s=>moveGymEntry(workout(s,d.workout).exercises,d.id,Number(d.delta)),'Ordem dos exercícios salva.');document.querySelector(`[data-gym-exercise="${d.id}"] [data-action="gym-move-exercise"]:not(:disabled)`)?.focus({preventScroll:true})}
      else if(name==='gym-export'){const s=load();const raw=s?JSON.stringify(s,null,2):repo.raw;if(raw!==null)download(raw,'retomar-academia-'+date()+'.json');else toast(error)}
      else if(name==='gym-import')document.querySelector('#gym-backup-file')?.click();
    }catch(e){toast(e.message)}
  }
  function updateToday(s){
    const root=document.querySelector('.gym-page'),day=date();
    if(!root||renderedDate!==day||JSON.stringify(s.preferences)!==JSON.stringify(preferences)||!s.preferences.showCompleted){render();return}
    const w=s.workouts.find(x=>x.id===root.dataset.gymWorkout);if(!w){render();return}
    const entries=s.sessions[day]||{},done=w.exercises.filter(e=>entries[e.id]).length;
    root.querySelectorAll('[data-gym-check]').forEach(input=>{const checked=entries[input.dataset.gymCheck]===true;input.checked=checked;input.disabled=false;input.closest('.gym-exercise').classList.toggle('gym-done',checked)});
    const summary=root.querySelector('.gym-progress-head span'),bar=root.querySelector('.gym-progress');if(summary)summary.textContent=`${done} de ${w.exercises.length} feitos hoje`;if(bar)bar.value=done;
  }
  function bind(){
    const root=document.querySelector('.gym-page');if(root)media.hydrate(root);
    document.querySelectorAll('[data-gym-check]').forEach(input=>{input.onchange=async()=>{const day=date();if(input.dataset.gymDate!==day){render();toast('Um novo dia começou. Confira as marcações de hoje.');return}const checked=input.checked,doc=input.ownerDocument,hadFocus=doc.activeElement===input;input.disabled=true;const ok=await save(s=>{const w=workout(s,input.dataset.workout);if(!w.exercises.some(e=>e.id===input.dataset.gymCheck))throw Error('Este exercício foi removido em outra janela.');s.sessions[day]||={};if(checked)s.sessions[day][input.dataset.gymCheck]=true;else delete s.sessions[day][input.dataset.gymCheck];},checked?'Exercício marcado como feito hoje.':'Marcação de hoje removida.',{refresh:updateToday});if(!ok){input.checked=!checked;input.disabled=false;}if(hadFocus&&doc.activeElement===doc.body)doc.getElementById(input.id)?.focus({preventScroll:true});}});
    const file=document.querySelector('#gym-backup-file');if(file)file.onchange=importFile;
  }
  target.addEventListener('storage',event=>{if(event.key===GYM_KEY){render();if(document.querySelector('dialog[open] #gym-exercise-form,dialog[open] #gym-workout-form'))toast('A Academia mudou em outra janela. Seu formulário foi preservado.')}});
  return {page,bind,action,canSwipe(delta){const s=load();if(!s||!s.preferences.swipe)return false;const i=s.workouts.findIndex(w=>w.id===selected);return i+delta>=0&&i+delta<s.workouts.length},swipe(delta){const s=load();if(!s||!s.preferences.swipe)return;const i=s.workouts.findIndex(w=>w.id===selected),next=s.workouts[i+delta];if(next){selected=next.id;render()}},refreshDate(){if(renderedDate&&renderedDate!==date())render()}};
}
